// HubSpot's "Send a webhook" action posts the enrolled deal; the template comes from the URL.
const TEMPLATES = ['first-reply', 'call-prep', 'proposal-nudge'];
const body = $input.first().json.body ?? {};
const query = $input.first().json.query ?? {};
const p = body.properties ?? {};
const raw = body.objectId ?? body.hs_object_id ?? p.hs_object_id?.value ?? p.hs_object_id;
const dealId = String(raw ?? '').trim();
if (!/^\d+$/.test(dealId)) throw new Error('No deal id in the HubSpot webhook body');
const template = String(query.template ?? '');
if (!TEMPLATES.includes(template)) throw new Error('Unknown draft template: ' + template.slice(0, 40));
return [{ json: { dealId, template } }];

// Decide whether to draft, and write the email. Contact fields are visitor input:
// nothing from them reaches a mail header without being checked.
const PIPELINE = '2630364862';
const STAGE = { NEW: '4456833770', CONTACTED: '4456833771', CALL: '4456833772', PROPOSAL: '4456833773', WON: '4456833775', LOST: '4456833776' };
const BOOKING_URL = 'https://calendly.com/lienkeinsley/intro-call';
// The opt-out line is what the site's consent copy and /privacy promise: keep them in step.
const SIGNATURE = 'Best,\nNeil\nTrust Cycle Agency (a portfolio project)\n\nRather not hear from us? Reply "unsubscribe" and I will remove your details.';
const SERVICES = { brand: 'brand and identity', website: 'website design and build', marketing: 'marketing and ads', seo: 'SEO and content', social: 'social media' };
const BUDGET = { 'under-5k': 'under $5k', '5k-15k': '$5k to $15k', '15k-50k': '$15k to $50k', '50k-plus': '$50k+', unsure: 'still to work out' };
const TIMELINE = { asap: 'as soon as possible', '1-3-months': 'in 1 to 3 months', '3-plus-months': '3+ months out', exploring: 'just exploring' };

const { dealId, template } = $('Find deal').first().json;
const deal = $('Read deal').first().json;
const cRes = $('Read contact').first().json;
const mRes = $('Read meetings').first().json;
const dp = deal.properties ?? {};
const contact = cRes.statusCode === 200 ? cRes.body : null;
const cp = contact?.properties ?? {};
const made = String(dp.tca_drafts_made ?? '').split(';').filter(Boolean);

const skip = (reason) => [{ json: { make: false, reason, dealId, template } }];
if (dp.pipeline !== PIPELINE) return skip('not a TCA new business deal');
if (made.includes(template)) return skip('draft already made for this deal');
if ([STAGE.WON, STAGE.LOST].includes(dp.dealstage)) return skip('deal is closed');
if (template === 'call-prep' && dp.dealstage !== STAGE.CALL) return skip('deal is not in Call booked');
if (template === 'proposal-nudge' && dp.dealstage !== STAGE.PROPOSAL) return skip('deal is no longer in Proposal sent');
if (!contact) return skip('no contact on the deal');
const to = String(cp.email ?? '').trim().toLowerCase();
if (!/^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/.test(to)) return skip('contact has no usable email');
if (!cp.tca_consent) return skip('no email consent recorded');

const clean = (s) => String(s ?? '').replace(/[\r\n\t]+/g, ' ').trim();
const first = clean(cp.firstname).slice(0, 40) || 'there';
const services = String(cp.tca_services ?? '').split(';').map((s) => SERVICES[s]).filter(Boolean);

let subject = '';
let text = '';
if (template === 'first-reply') {
  const budget = BUDGET[dp.tca_budget ?? cp.tca_budget];
  const timeline = TIMELINE[dp.tca_timeline ?? cp.tca_timeline];
  const facts = [services.length ? '- Services: ' + services.join(', ') : null, budget ? '- Budget: ' + budget : null, timeline ? '- Timeline: ' + timeline : null].filter(Boolean);
  subject = services.length ? 'Next steps for your ' + services[0] + ' project' : 'Next steps for your project';
  const next = dp.dealstage === STAGE.CALL
    ? 'I can see you have already booked a call, so I will send a few questions ahead of it.'
    : 'The best next step is a free 30-minute intro call, where we go through your goals and see whether we are a good fit. You can pick a time that suits you here:\n' + BOOKING_URL + '\n\nIf you would rather not have a call, just reply to this email with anything you would like to add.';
  text = 'Hi ' + first + ',\n\nThanks for sending over your project details.' + (facts.length ? ' Here is what you told us:\n' + facts.join('\n') : '') + '\n\n' + next + '\n\n' + SIGNATURE;
} else if (template === 'call-prep') {
  const meetings = (mRes.statusCode === 200 || mRes.statusCode === 207) ? (mRes.body?.results ?? []) : [];
  const m = meetings
    .filter((x) => x.properties?.hs_meeting_outcome === 'SCHEDULED' && Date.parse(x.properties?.hs_meeting_start_time) > Date.now())
    .sort((a, b) => Date.parse(a.properties.hs_meeting_start_time) - Date.parse(b.properties.hs_meeting_start_time))[0];
  if (!m) return skip('no upcoming scheduled meeting on the deal');
  const start = new Date(m.properties.hs_meeting_start_time);
  const fmt = (o) => new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Manila', ...o }).format(start);
  const day = fmt({ weekday: 'short', day: 'numeric', month: 'short' });
  const loc = String(m.properties.hs_meeting_location ?? '');
  subject = 'Before our call on ' + day;
  text = 'Hi ' + first + ',\n\nThanks for booking a call. The details:\n'
    + 'When: ' + fmt({ weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }) + ' (Manila time, UTC+8)\n'
    + 'Where: ' + (loc.startsWith('https://') ? loc : 'the video link in your Calendly confirmation') + '\n\n'
    + 'To make the most of the 30 minutes, it would help to know:\n'
    + '1. What made now the right time to look for help?\n'
    + '2. Is there a website, brand or campaign you would point to as a good example?\n'
    + '3. Who else will be part of the decision?\n\n'
    + 'Short answers are fine, or we can cover them on the call.\n\n' + SIGNATURE;
} else {
  subject = 'Following up on the proposal';
  text = 'Hi ' + first + ',\n\nI wanted to check whether you have had a chance to look over the proposal. If any part of the scope or timing does not fit, I am happy to adjust it, or to walk through it on a short call.\n\n' + SIGNATURE;
}

// RFC 2822 message, base64url-encoded for Gmail's drafts.create (no Buffer needed).
const utf8 = (s) => unescape(encodeURIComponent(s));
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const b64 = (bin) => {
  let out = '';
  for (let i = 0; i < bin.length; i += 3) {
    const a = bin.charCodeAt(i), b = bin.charCodeAt(i + 1), c = bin.charCodeAt(i + 2);
    const n = (a << 16) | ((b || 0) << 8) | (c || 0);
    out += B64[(n >> 18) & 63] + B64[(n >> 12) & 63] + (i + 1 < bin.length ? B64[(n >> 6) & 63] : '=') + (i + 2 < bin.length ? B64[n & 63] : '=');
  }
  return out;
};
const mime = [
  'To: ' + to,
  'Subject: =?UTF-8?B?' + b64(utf8(clean(subject))) + '?=',
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  b64(utf8(text)).replace(/.{76}/g, '$&\r\n'),
].join('\r\n');
const raw = b64(mime).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: {
  make: true,
  dealId,
  template,
  to,
  subject,
  draftBody: { message: { raw } },
  noteBody: {
    properties: {
      hs_timestamp: new Date().toISOString(),
      hs_note_body: '<p><strong>Gmail draft ready</strong> (' + esc(template) + ') for ' + esc(to) + ': "' + esc(subject) + '". Review and send it from Gmail Drafts.</p>',
    },
    associations: [{ to: { id: dealId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 214 }] }],
  },
} }];
